{"path":"workflow.py","content":""""订单对账 v1 实现。

契约见 spec-v1.md：输入为 UTF-8 CSV 字符串，输出使用整数分（Decimal 定点，不用 float）。
"""

import csv
import io
import json
from decimal import Decimal, InvalidOperation

_ORDERS_REQUIRED = ("order_id", "customer", "amount", "status")
_REFUNDS_REQUIRED = ("refund_id", "order_id", "amount")
_PAID = "paid"
_CANCELLED = "cancelled"


def _amount_to_cents(raw, context):
    """把金额字符串转成整数分；拒绝 NaN/Infinity/负数/超过两位小数。"""
    if raw is None:
        raise ValueError("%s: 缺少金额字段" % context)
    text = raw.strip()
    if text == "":
        raise ValueError("%s: 金额为空" % context)
    try:
        value = Decimal(text)
    except (InvalidOperation, ValueError):
        raise ValueError("%s: 金额无法解析: %r" % (context, raw))
    if not value.is_finite():
        raise ValueError("%s: 金额必须是有限数: %r" % (context, raw))
    if value < 0:
        raise ValueError("%s: 金额不能为负: %r" % (context, raw))
    exponent = value.as_tuple().exponent
    if not isinstance(exponent, int) or exponent < -2:
        raise ValueError("%s: 金额最多两位小数: %r" % (context, raw))
    cents = int(value.scaleb(2).to_integral_value())
    return cents


def _read_rows(csv_text, required, kind):
    """读取 CSV 字符串，返回 (header, rows)；不修改输入内容。"""
    if csv_text is None:
        raise ValueError("%s: 输入必须是字符串" % kind)
    if not isinstance(csv_text, str):
        raise ValueError("%s: 输入必须是字符串" % kind)
    reader = csv.DictReader(io.StringIO(csv_text))
    header = reader.fieldnames
    if header is None:
        return [], []
    missing = [name for name in required if name not in header]
    if missing:
        raise ValueError("%s: 缺少列 %s" % (kind, ",".join(missing)))
    rows = []
    for index, row in enumerate(reader, start=2):
        if row.get(None) is not None:
            raise ValueError("%s 第%d行: 字段过多" % (kind, index))
        values = {}
        for name in header:
            if name is None:
                continue
            value = row.get(name)
            if value is None:
                raise ValueError("%s 第%d行: 缺少列 %s" % (kind, index, name))
            values[name] = value.strip()
        if all(value == "" for value in values.values()):
            continue
        rows.append(values)
    return header, rows


def _index_unique(rows, id_field, kind):
    """按 id 去重：完全相同的行只算一次；同 id 但字段不同抛 ValueError。"""
    seen = {}
    unique = []
    for row in rows:
        key = row.get(id_field, "")
        if key == "":
            raise ValueError("%s: %s 不能为空" % (kind, id_field))
        signature = tuple(row.get(name, "") for name in sorted(row))
        if key in seen:
            if seen[key] != signature:
                raise ValueError(
                    "%s %s 重复但字段不一致" % (kind, id_field)
                )
            continue
        seen[key] = signature
        unique.append(row)
    return unique


def reconcile(orders_csv, refunds_csv, policy="v1", cutoff=None):
    """按 v1 契约对账，返回 orders / customers / totals。"""
    if policy not in ("v1", "v2"):
        raise ValueError("未知 policy: %r" % (policy,))

    _, order_rows = _read_rows(orders_csv, _ORDERS_REQUIRED, "orders")
    _, refund_rows = _read_rows(refunds_csv, _REFUNDS_REQUIRED, "refunds")

    order_rows = _index_unique(order_rows, "order_id", "orders")
    refund_rows = _index_unique(refund_rows, "refund_id", "refunds")

    orders = {}
    for row in order_rows:
        order_id = row["order_id"]
        customer = row["customer"]
        status = row["status"]
        if customer == "":
            raise ValueError("orders: customer 不能为空")
        if status not in (_PAID, _CANCELLED):
            raise ValueError("orders: 未知 status %r" % (status,))
        paid_cents = _amount_to_cents(row["amount"], "orders %s" % order_id)
        orders[order_id] = {
            "order_id": order_id,
            "customer": customer,
            "status": status,
            "paid_cents": paid_cents,
        }

    refund_by_order = {}
    for row in refund_rows:
        refund_id = row["refund_id"]
        order_id = row["order_id"]
        order = orders.get(order_id)
        if order is None:
            raise ValueError("refunds %s: 未知订单 %s" % (refund_id, order_id))
        if order["status"] != _PAID:
            raise ValueError(
                "refunds %s: 订单 %s 不是 paid 状态" % (refund_id, order_id)
            )
        amount_cents = _amount_to_cents(row["amount"], "refunds %s" % refund_id)
        refund_by_order[order_id] = refund_by_order.get(order_id, 0) + amount_cents

    for order_id, order in orders.items():
        if order["status"] != _PAID:
            continue
        refunded = refund_by_order.get(order_id, 0)
        if refunded > order["paid_cents"]:
            raise ValueError(
                "订单 %s 累计退款 %d 超过已付 %d"
                % (order_id, refunded, order["paid_cents"])
            )

    result_orders = []
    customer_totals = {}
    total_paid = 0
    total_refund = 0
    for order_id in sorted(orders):
        order = orders[order_id]
        if order["status"] != _PAID:
            continue
        paid_cents = order["paid_cents"]
        refund_cents = refund_by_order.get(order_id, 0)
        net_cents = paid_cents - refund_cents
        result_orders.append({
            "order_id": order_id,
            "customer": order["customer"],
            "paid_cents": paid_cents,
            "refund_cents": refund_cents,
            "net_cents": net_cents,
        })
        customer_totals[order["customer"]] = (
            customer_totals.get(order["customer"], 0) + net_cents
        )
        total_paid += paid_cents
        total_refund += refund_cents

    customers = [
        {"customer": name, "net_cents": customer_totals[name]}
        for name in sorted(customer_totals)
    ]
    return {
        "orders": result_orders,
        "customers": customers,
        "totals": {
            "paid_cents": total_paid,
            "refund_cents": total_refund,
            "net_cents": total_paid - total_refund,
        },
    }


def export_bundle(result):
    """把对账结果导出为可序列化的文件集合（确定性 JSON）。"""
    summary = {
        "totals": result["totals"],
        "customers": result["customers"],
    }
    return {
        "summary.json": json.dumps(
            summary, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        ),
        "orders.json": json.dumps(
            result["orders"], sort_keys=True, separators=(",", ":"), ensure_ascii=False
        ),
    }
"}
